 $('accountList').innerHTML=data.accounts.length?data.accounts.map(a=>`<div class="detail-head account-row"><span>${esc(a.emoji||'🏦')} ${esc(a.name)}</span><b>${money(a.balance)}</b><span><button class="icon-btn" onclick="editAccount('${a.id}')" aria-label="Modifier le compte">✎</button><button class="icon-btn" onclick="deleteAccount('${a.id}')" aria-label="Supprimer le compte">×</button></span></div>`).join(''):'<div class="empty">Crée ton premier compte épargne.</div>';
