['customBg','customPrimary','customAccent'].forEach(id=>$(id).addEventListener('input',()=>{appearanceColorsEdited=true;}));
function exportJSON(){data.settings.periods=data.settings.periods||{};const currentPeriod=periodFor(month);const openingField=$('opening');if(openingField&&openingField.value!==''){data.settings.periods[month]={...currentPeriod,openingBalance:Number(openingField.value)||0};}localStorage.setItem('monBudgetDataV3',JSON.stringify(data));let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mon-budget-sauvegarde-'+today()+'.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}$('importJSON').addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;try{let obj=JSON.parse(await f.text());if(!obj.categories||!obj.transactions||!obj.settings)throw Error('format');if(!confirm('Importer cette sauvegarde remplacera les données actuelles. Continuer ?'))return;data=migrate(obj);persist();alert('Sauvegarde importée.')}catch{alert('Fichier JSON invalide ou incompatible.')}e.target.value=''});function resetAll(){if(!confirm('Effacer toutes les données ? Exporte d’abord une sauvegarde JSON.'))return;data=clone(seed);persist()}
