function setNumericKeyboards(root=document){root.querySelectorAll('input[type=number]').forEach(el=>{el.setAttribute('inputmode',el.step&&el.step!== '1'?'decimal':'numeric');if(el.dataset.zeroFocusBound)return;el.dataset.zeroFocusBound='1';el.addEventListener('focus',()=>{if(el.value!==''&&Number(el.value)===0){el.dataset.restoreZero='1';el.value='';}});el.addEventListener('blur',()=>{if(el.dataset.restoreZero==='1'&&el.value.trim()===''){el.value='0';}delete el.dataset.restoreZero;});});}const observer=new MutationObserver(()=>setNumericKeyboards());observer.observe(document.body,{childList:true,subtree:true});setNumericKeyboards();
